CREATE EXTENSION IF NOT EXISTS  dblink ;
DO $$
    BEGIN
    IF NOT EXISTS (
        SELECT
        FROM   pg_catalog.pg_database
        WHERE  datname = 'MasiSale'
    ) THEN
        PERFORM dblink_exec('dbname=' || current_database() || ' user=' || current_user, 'CREATE DATABASE "MasiSale"');
    END IF;
    END
$$;
